<?php require __DIR__.'/../config/database.php';require_login();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['full_name']??''));$phone=trim((string)($_POST['phone']??''));if(mb_strlen($name)<2||mb_strlen($name)>100)$error='Tên cần từ 2 đến 100 ký tự.';else{$st=$pdo->prepare('UPDATE users SET full_name=?,phone=? WHERE id=?');$st->execute([$name,$phone?:null,current_user()['id']]);$_SESSION['user']['full_name']=$name;flash('Đã cập nhật hồ sơ.');redirect('/user/profile.php');}}$st=$pdo->prepare('SELECT full_name,email,phone FROM users WHERE id=?');$st->execute([current_user()['id']]);$u=$st->fetch();$pageTitle='Hồ sơ';require __DIR__.'/../includes/header.php';?><div class="card card-body form-card"><h1 class="h3">Thông tin cá nhân</h1><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post"><?= csrf_field() ?><label class="form-label">Họ tên</label><input class="form-control mb-3" name="full_name" value="<?= e($u['full_name']) ?>" required><label class="form-label">Email</label><input class="form-control mb-3" value="<?= e($u['email']) ?>" disabled><label class="form-label">Điện thoại</label><input class="form-control mb-3" name="phone" value="<?= e($u['phone']) ?>"><button class="btn btn-success">Lưu thay đổi</button></form></div><?php require __DIR__.'/../includes/footer.php'; ?>
